def test_create_then_read_repository(
    client
):
    created = client.post(
        "/repositories",
        json={
            "name": "demo",
            "url": "https://example.com/repo"
        }
    )

    assert created.status_code == 201

    repo_id = created.json()["id"]

    fetched = client.get(
        f"/repositories/{repo_id}"
    )

    assert fetched.status_code == 200
    assert fetched.json()["name"] == "demo"

